    """
    # Ensure max_val covers floor(x) and ceil(x)
    min_needed = max(int(x), int(x) + 1)
    if max_val < min_needed + 100:
        max_val = min_needed + 100

    # Initialize cache with safe boundary values
    cache = {}
    for i in range(1, max_val + 1):
        if i <= 1:
            cache[i] = 1.0
        elif i > 100:  # Approximate tail where prob is very small
            cache[i] = 0.0
        else:
            cache[i] = 0.0

    # Iterate until convergence
    for _ in range(iterations):
        changed = False
        for val in range(min(150, max_val), 2, -1):
            # Compute arguments with proper boundary handling
            arg1 = 2 * val - 2
            arg2 = 2 * val - 4

            def get_prob(arg):
                if arg <= 1:
                    return 1.0
                if arg > max_val:
                    return 0.0
                return cache.get(arg, 0.0)

            p_heads = get_prob(arg1)
            p_tails = get_prob(arg2)
            new_p = 0.5 * p_heads + 0.5 * p_tails

            old_p = cache.get(val, 0.0)
            if abs(new_p - old_p) > 1e-12:
                cache[val] = new_p
                changed = True

